using UnityEngine;

/// <summary>
/// Buff 效果抽象基类 — 策略模式，定义 Buff 在生命周期各阶段的行为。
/// 每个具体效果是独立的 ScriptableObject 资产。
/// </summary>
public abstract class BuffEffectBase : ScriptableObject
{
    /// <summary>Buff 被应用到目标时调用（只调用一次）</summary>
    public abstract void OnApply(GameObject target, BuffInstance buff);

    /// <summary>Buff 被移除时调用（只调用一次）</summary>
    public abstract void OnRemove(GameObject target, BuffInstance buff);

    /// <summary>每帧 Tick（由 BuffManager 驱动），默认空实现</summary>
    public virtual void OnTick(GameObject target, BuffInstance buff, float deltaTime) { }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Buff 运行时实例 — 纯 C# class，非 MonoBehaviour。
/// 由 BuffManager 创建和管理生命周期。
/// 设计目标: 避免每个 Buff 创建 GameObject，统一由 BuffManager 的 Update 驱动 Tick。
/// </summary>
public class BuffInstance
{
    /// <summary>Buff 数据定义</summary>
    public BuffData Data { get; }

    /// <summary>挂载的目标 GameObject</summary>
    public GameObject Owner { get; }

    /// <summary>施放者（用于伤害归属等）</summary>
    public GameObject Caster { get; }

    /// <summary>当前堆叠数</summary>
    public int CurrentStacks { get; private set; } = 1;

    /// <summary>剩余持续时间（秒）</summary>
    public float RemainingDuration { get; private set; }

    /// <summary>已流逝时间（秒）</summary>
    public float ElapsedTime { get; private set; }

    /// <summary>是否已过期</summary>
    public bool IsExpired => !Data.isPermanent && RemainingDuration <= 0f;

    /// <summary>是否活跃</summary>
    public bool IsActive { get; set; } = true;

    /// <summary>不可清除标记（藏品/道具等来源的 buff，净化类技能不可清除）</summary>
    public bool Indestructible { get; set; }

    /// <summary>独立计时模式下每个堆叠的剩余时间</summary>
    private readonly List<float> _stackTimers = new List<float>();

    public BuffInstance(BuffData data, GameObject owner, GameObject caster)
    {
        Data = data;
        Owner = owner;
        Caster = caster;
        RemainingDuration = data.duration;
        _stackTimers.Add(data.duration);
    }

    /// <summary>添加堆叠</summary>
    public void AddStack()
    {
        if (!Data.stackable || CurrentStacks >= Data.maxStacks)
            return;

        switch (Data.stackBehavior)
        {
            case StackBehavior.Refresh:
                RemainingDuration = Data.duration;
                break;
            case StackBehavior.Independent:
                _stackTimers.Add(Data.duration);
                break;
            case StackBehavior.ExtendDuration:
                RemainingDuration += Data.duration;
                break;
        }
        CurrentStacks++;
    }

    /// <summary>刷新持续时间到初始值（Refresh 行为；供"在圈内停留持续刷新 debuff"场景使用）</summary>
    public void RefreshDuration()
    {
        RemainingDuration = Data.duration;
    }

    /// <summary>延长持续时间（ExtendDuration 行为）</summary>
    public void ExtendDuration(float amount)
    {
        RemainingDuration += amount;
    }

    /// <summary>直接设置剩余持续时间（偷取/转移 buff 等机制使用）</summary>
    public void SetRemainingDuration(float duration)
    {
        RemainingDuration = Mathf.Max(duration, 0f);
    }

    /// <summary>Tick — 由 BuffManager 调用</summary>
    public void Tick(float deltaTime)
    {
        if (!IsActive || Data.isPermanent)
            return;

        // Independent 模式：每帧 tick 所有独立堆叠
        if (Data.stackBehavior == StackBehavior.Independent)
        {
            for (int i = _stackTimers.Count - 1; i >= 0; i--)
            {
                _stackTimers[i] -= deltaTime;
                if (_stackTimers[i] <= 0f)
                {
                    _stackTimers.RemoveAt(i);
                    CurrentStacks--;
                }
            }
            RemainingDuration = _stackTimers.Count > 0 ? _stackTimers[^1] : -1f;
        }
        else
        {
            RemainingDuration -= deltaTime;
        }

        ElapsedTime += deltaTime;

        // 驱动效果 Tick
        Data.effect?.OnTick(Owner, this, deltaTime);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Buff 管理器 — 挂载到需要接收 Buff 的 GameObject 上。
/// 管理所有活跃 Buff 的生命周期（Apply / Tick / Remove）。
///
/// 用法: 挂载到 Player / Enemy Prefab 上，通过 ApplyBuff(BuffData) 添加 Buff。
/// </summary>
public class BuffManager : MonoBehaviour
{
    private readonly List<BuffInstance> _activeBuffs = new List<BuffInstance>();
    private readonly Dictionary<string, List<BuffInstance>> _buffDict = new Dictionary<string, List<BuffInstance>>();

    // 待移除队列 — 避免在迭代中修改集合
    private readonly List<BuffInstance> _pendingRemoval = new List<BuffInstance>();

    /// <summary>当前活跃 Buff 列表（只读）</summary>
    public IReadOnlyList<BuffInstance> ActiveBuffs => _activeBuffs;

    // ========== 事件 ==========

    /// <summary>Buff 被应用: (buff)</summary>
    public event Action<BuffInstance> OnBuffApplied;
    /// <summary>Buff 被移除: (buff)</summary>
    public event Action<BuffInstance> OnBuffRemoved;
    /// <summary>Buff 堆叠变化: (buff)</summary>
    public event Action<BuffInstance> OnBuffStackChanged;

    // ========== 核心方法 ==========

    /// <summary>
    /// 应用 Buff。如果同 ID Buff 已存在且可叠加，则尝试叠加；
    /// 否则创建新 BuffInstance。
    /// </summary>
    public BuffInstance ApplyBuff(BuffData data, GameObject caster = null)
    {
        if (data == null) return null;

        // 免疫检查：被免疫的 buffId 直接拒绝施加
        if (_immuneBuffIds.Contains(data.buffId))
            return null;

        // 检查是否已有同 ID 的 Buff
        if (_buffDict.TryGetValue(data.buffId, out var existingList) && existingList.Count > 0)
        {
            var existing = existingList[0];

            // 可叠加且未满栈：叠加
            if (data.stackable && existing.CurrentStacks < data.maxStacks)
            {
                existing.AddStack();
                OnBuffStackChanged?.Invoke(existing);
                return existing;
            }

            // 不可叠加 / 已满栈：按叠加行为刷新或延长持续时间
            if (!data.isPermanent)
            {
                switch (data.stackBehavior)
                {
                    case StackBehavior.Refresh:
                        existing.RefreshDuration();
                        break;
                    case StackBehavior.ExtendDuration:
                        existing.ExtendDuration(data.duration);
                        break;
                    case StackBehavior.Independent:
                        // Independent 不可叠加时不刷新（保持独立计时）
                        break;
                }
                OnBuffStackChanged?.Invoke(existing);
            }
            return existing;
        }

        var buff = new BuffInstance(data, gameObject, caster);
        _activeBuffs.Add(buff);

        if (!_buffDict.ContainsKey(data.buffId))
            _buffDict[data.buffId] = new List<BuffInstance>();
        _buffDict[data.buffId].Add(buff);

        data.effect?.OnApply(gameObject, buff);
        OnBuffApplied?.Invoke(buff);
        return buff;
    }

    /// <summary>移除指定 Buff 实例</summary>
    public void RemoveBuff(BuffInstance buff)
    {
        if (buff == null || _pendingRemoval.Contains(buff)) return;
        _pendingRemoval.Add(buff);
    }

    /// <summary>移除指定 ID 的所有 Buff</summary>
    public void RemoveBuffById(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            for (int i = list.Count - 1; i >= 0; i--)
                RemoveBuff(list[i]);
        }
    }

    /// <summary>
    /// 清除所有可净化的 Debuff（排除 Indestructible 标记的藏品/道具 debuff）。
    /// 返回被清除的 debuff 数量。
    /// </summary>
    public int RemoveAllDebuffs()
    {
        var toRemove = new List<BuffInstance>();
        foreach (var buff in _activeBuffs)
        {
            if (buff == null) continue;
            if (buff.Data.buffType == BuffType.Debuff && !buff.Indestructible)
                toRemove.Add(buff);
        }

        foreach (var buff in toRemove)
            RemoveBuff(buff);

        return toRemove.Count;
    }

    /// <summary>是否有指定 Buff</summary>
    public bool HasBuff(string buffId) =>
        _buffDict.TryGetValue(buffId, out var list) && list.Count > 0;

    /// <summary>获取指定 ID 的第一个 Buff 实例</summary>
    public BuffInstance GetBuff(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list) && list.Count > 0)
            return list[0];
        return null;
    }

    /// <summary>获取指定 ID 的所有 Buff 实例</summary>
    public IReadOnlyList<BuffInstance> GetBuffs(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
            return list;
        return System.Array.Empty<BuffInstance>();
    }

    /// <summary>获取 Buff 堆叠总数（所有同 ID Buff 的堆叠和）</summary>
    public int GetBuffStackCount(string buffId)
    {
        int total = 0;
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            foreach (var b in list)
                total += b.CurrentStacks;
        }
        return total;
    }

    // ========== Buff 免疫 ==========

    private readonly HashSet<string> _immuneBuffIds = new HashSet<string>();

    /// <summary>添加对指定 buffId 的免疫（阻止该 Buff 被施加）</summary>
    public void AddBuffImmunity(string buffId)
    {
        _immuneBuffIds.Add(buffId);
    }

    /// <summary>移除对指定 buffId 的免疫</summary>
    public void RemoveBuffImmunity(string buffId)
    {
        _immuneBuffIds.Remove(buffId);
    }

    // ========== Unity 生命周期 ==========

    private void Update()
    {
        float dt = Time.deltaTime;

        // Tick 所有活跃 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            if (buff.IsActive)
                buff.Tick(dt);
        }

        // 处理过期 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            if (!_activeBuffs[i].IsActive || _activeBuffs[i].IsExpired)
                _pendingRemoval.Add(_activeBuffs[i]);
        }

        // 执行待移除
        ProcessRemovalQueue();
    }

    private void ProcessRemovalQueue()
    {
        for (int i = 0; i < _pendingRemoval.Count; i++)
        {
            var buff = _pendingRemoval[i];
            if (buff == null) continue;

            buff.IsActive = false;
            buff.Data.effect?.OnRemove(gameObject, buff);
            _activeBuffs.Remove(buff);

            if (_buffDict.TryGetValue(buff.Data.buffId, out var list))
            {
                list.Remove(buff);
                if (list.Count == 0)
                    _buffDict.Remove(buff.Data.buffId);
            }

            OnBuffRemoved?.Invoke(buff);
        }
        _pendingRemoval.Clear();
    }

    private void OnDestroy()
    {
        // 清理所有 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            buff.Data.effect?.OnRemove(gameObject, buff);
        }
        _activeBuffs.Clear();
        _buffDict.Clear();
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 挂载 Buff 道具效果 — 获得道具时给持有者挂载一个 Buff。
/// 每次 OnAcquire 创建新 Buff 实例，支持叠加持有。
/// 移除时销毁最后一个 Buff。
/// </summary>
[CreateAssetMenu(fileName = "ApplyBuffEffect", menuName = "Game/Item Effect/Apply Buff")]
public class ApplyBuffEffect : ItemEffectBase
{
    [Header("Buff 配置")]
    [Tooltip("要挂载的 Buff 数据资产")]
    public BuffData buffData;

    /// <summary>已挂载的 Buff 实例列表（用于逐层移除）</summary>
    private readonly List<BuffInstance> _appliedBuffs = new List<BuffInstance>();

    public override void OnAcquire(GameObject owner)
    {
        if (buffData == null)
        {
            Debug.LogWarning("ApplyBuffEffect: buffData 为空！");
            return;
        }

        var buffManager = owner.GetComponent<BuffManager>();
        if (buffManager == null)
        {
            Debug.LogWarning($"ApplyBuffEffect: owner '{owner.name}' 没有 BuffManager 组件");
            return;
        }

        var instance = buffManager.ApplyBuff(buffData, owner);

        // 藏品（道具）来源的 buff 不可被净化类技能清除
        if (instance != null)
            instance.Indestructible = true;

        _appliedBuffs.Add(instance);
    }

    public override void OnRemove(GameObject owner)
    {
        if (_appliedBuffs.Count == 0) return;

        var buffManager = owner.GetComponent<BuffManager>();
        if (buffManager == null) return;

        // 移除最后一个（LIFO）
        int lastIndex = _appliedBuffs.Count - 1;
        var instance = _appliedBuffs[lastIndex];
        _appliedBuffs.RemoveAt(lastIndex);

        buffManager.RemoveBuff(instance);
    }
}

using UnityEngine;

/// <summary>
/// 道具效果抽象基类 — 策略模式，定义道具被获得/移除时的行为。
/// 与 SkillEffectBase 类似，每个具体效果是独立的 ScriptableObject 资产。
///
/// 子类:
///   StatModifierEffect — 直接修改属性
///   ApplyBuffEffect    — 挂载 Buff（道具系统与 Buff 系统的主要桥接）
///   ConditionalEffect  — 条件触发效果
/// </summary>
public abstract class ItemEffectBase : ScriptableObject
{
    /// <summary>道具被获得时调用</summary>
    public abstract void OnAcquire(GameObject owner);

    /// <summary>道具被移除时调用（清理副作用）</summary>
    public abstract void OnRemove(GameObject owner);
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 游戏统计单例 (DontDestroyOnLoad) — 追踪一局游戏的所有累计数据。
/// 
/// 生命周期:
///   Start 场景 → 销毁
///   游戏场景   → 创建/重置
///   Result 场景 → 保留 (供结算UI读取)
/// 
/// 订阅各系统事件，累计:
///   - 获得 / 消费的货币
///   - 获得的道具列表（含重复获取次数）
///   - 各类型房间的访问/清空数
///   - 各类型敌人的击杀数
/// </summary>
public class GameStatistics : MonoBehaviour
{
    public static GameStatistics Instance { get; private set; }

    // ========== 货币 ==========
    public int TotalCurrencyEarned { get; private set; }
    public int TotalCurrencySpent { get; private set; }

    // ========== 道具 ==========
    private readonly Dictionary<string, (ItemData data, int count)> _acquiredItems = new();
    /// <summary>累计获得的道具 (itemId → (ItemData, 获取次数))</summary>
    public IReadOnlyDictionary<string, (ItemData data, int count)> AcquiredItems => _acquiredItems;

    // ========== 房间 ==========
    private readonly Dictionary<RoomType, int> _roomsVisitedByType = new();
    private readonly Dictionary<RoomType, int> _roomsClearedByType = new();

    /// <summary>各房间类型的进入次数</summary>
    public IReadOnlyDictionary<RoomType, int> RoomsVisitedByType => _roomsVisitedByType;
    /// <summary>各房间类型的清空次数</summary>
    public IReadOnlyDictionary<RoomType, int> RoomsClearedByType => _roomsClearedByType;

    /// <summary>总进入房间数</summary>
    public int RoomsVisited { get; private set; }
    /// <summary>总清空房间数</summary>
    public int RoomsCleared { get; private set; }

    // ========== 击杀 ==========
    private readonly Dictionary<string, int> _enemiesKilled = new();
    /// <summary>敌人显示名 → 击杀数</summary>
    public IReadOnlyDictionary<string, int> EnemiesKilled => _enemiesKilled;

    // ========== 内部 ==========
    private CurrencyManager _boundCurrency;

    // ==================== 生命周期 ====================

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    private void OnEnable()
    {
        EnemyCore.OnAnyEnemyDied += OnEnemyDied;
    }

    private void OnDisable()
    {
        UnbindAll();
        EnemyCore.OnAnyEnemyDied -= OnEnemyDied;
    }

    private void OnDestroy()
    {
        UnbindAll();
        if (Instance == this)
            Instance = null;
    }

    // ==================== 绑定 / 解绑 ====================

    /// <summary>绑定 Player 身上的组件事件（货币/道具）</summary>
    public void BindPlayer(GameObject player)
    {
        if (player == null) return;

        var cm = player.GetComponent<CurrencyManager>();
        if (cm != null)
        {
            cm.OnCurrencyEarned += OnCurrencyEarned;
            cm.OnCurrencySpent += OnCurrencySpent;
            _boundCurrency = cm;
        }

        var im = player.GetComponent<ItemManager>();
        if (im != null)
        {
            im.OnItemAcquired += OnItemAcquired;
        }
    }

    /// <summary>解绑所有 Player 事件</summary>
    private void UnbindAll()
    {
        if (_boundCurrency != null)
        {
            _boundCurrency.OnCurrencyEarned -= OnCurrencyEarned;
            _boundCurrency.OnCurrencySpent -= OnCurrencySpent;
            _boundCurrency = null;
        }
    }

    // ==================== 事件回调 ====================

    private void OnCurrencyEarned(int amount)
    {
        TotalCurrencyEarned += amount;
    }

    private void OnCurrencySpent(int amount)
    {
        TotalCurrencySpent += amount;
    }

    private void OnItemAcquired(ItemData item)
    {
        if (item == null) return;

        string id = string.IsNullOrEmpty(item.itemId) ? item.name : item.itemId;
        if (_acquiredItems.TryGetValue(id, out var entry))
            _acquiredItems[id] = (entry.data, entry.count + 1);
        else
            _acquiredItems[id] = (item, 1);
    }

    private void OnEnemyDied(EnemyCore enemy)
    {
        if (enemy == null) return;

        string enemyName;
        if (enemy.config != null)
        {
            enemyName = !string.IsNullOrEmpty(enemy.config.displayName)
                ? enemy.config.displayName
                : enemy.config.name;
        }
        else
        {
            enemyName = enemy.name;
        }

        _enemiesKilled.TryGetValue(enemyName, out int count);
        _enemiesKilled[enemyName] = count + 1;
    }

    // ==================== 房间 ====================

    public void RecordRoomVisited(RoomType roomType)
    {
        RoomsVisited++;
        _roomsVisitedByType.TryGetValue(roomType, out int v);
        _roomsVisitedByType[roomType] = v + 1;
    }

    public void RecordRoomCleared(RoomType roomType)
    {
        RoomsCleared++;
        _roomsClearedByType.TryGetValue(roomType, out int v);
        _roomsClearedByType[roomType] = v + 1;
    }

    // ==================== 重置 ====================

    /// <summary>清空所有统计数据（新一局开始时调用）</summary>
    public void ResetAll()
    {
        TotalCurrencyEarned = 0;
        TotalCurrencySpent = 0;
        _acquiredItems.Clear();
        RoomsVisited = 0;
        RoomsCleared = 0;
        _roomsVisitedByType.Clear();
        _roomsClearedByType.Clear();
        _enemiesKilled.Clear();
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

/// <summary>
/// Result 场景结算控制器 —— 主屏幕仅显示标题 + 按钮；
/// 点击 "查看结算" 按钮弹出新 UI 面板，展示全部结算数据与评分明细。
///
/// 挂在 Result 场景的 Canvas 上。
/// 通过 [SerializeField] 引用 ScoreCalculator 和各 TMP_Text 组件。
/// </summary>
public class ResultSceneController : MonoBehaviour
{
    [Header("分数计算器")]
    [SerializeField] private ScoreCalculator _scoreCalculator;

    [Header("Replay / Exit 按钮")]
    [SerializeField] private Button _replayButton;
    [SerializeField] private Button _exitButton;
    [SerializeField] private string _replaySceneName = "Start";

    [Header("主屏幕标题文本")]
    [SerializeField] private TMP_Text _titleText;

    [Header("唤起结算面板的按钮")]
    [SerializeField] private Button _openSettlementButton;

    [Header("结算弹窗 (场景中预置)")]
    [SerializeField] private GameObject _settlementPanel;
    [SerializeField] private GameObject _settlementOverlay;
    [SerializeField] private Button _closeSettlementButton;
    [SerializeField] private TMP_Text _panelTitleText;
    [SerializeField] private TMP_Text _panelScoreText;
    [SerializeField] private TMP_Text _panelDetailText;

    [Header("弹窗背景颜色")]
    [SerializeField] private Color _panelBackgroundColor = Color.black;

    [Header("科技点")]
    [Tooltip("分数 ÷ 此值 = 获得的科技点")]
    [SerializeField] private int _techPointDivisor = 1000;

    private bool _techPointsAwarded = false;
    private int _lastEarnedTechPoints = 0;

    private void Start()
    {
        if (_replayButton != null)
            _replayButton.onClick.AddListener(OnReplay);
        if (_exitButton != null)
            _exitButton.onClick.AddListener(OnExit);

        if (_openSettlementButton != null)
            _openSettlementButton.onClick.AddListener(OnOpenSettlement);

        if (_closeSettlementButton != null)
            _closeSettlementButton.onClick.AddListener(OnCloseSettlement);

        if (_settlementOverlay != null)
        {
            var overlayBtn = _settlementOverlay.GetComponent<Button>();
            if (overlayBtn != null)
                overlayBtn.onClick.AddListener(OnCloseSettlement);
        }

        if (_settlementPanel != null)
            _settlementPanel.gameObject.SetActive(false);
        if (_settlementOverlay != null)
            _settlementOverlay.gameObject.SetActive(false);

        DisplayTitle();
    }

    private void OnReplay()
    {
        // 重置道具池（新一局开始）
        if (ItemsLibrary.Instance != null)
            ItemsLibrary.Instance.ResetPool();

        SceneManager.LoadScene(_replaySceneName);
    }

    private void OnExit()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    // ==================== 结算弹窗 ====================

    private void OnOpenSettlement()
    {
        if (_settlementPanel == null) return;

        _settlementPanel.SetActive(true);
        if (_settlementOverlay != null)
            _settlementOverlay.SetActive(true);

        var img = _settlementPanel.GetComponent<Image>();
        if (img != null)
            img.color = _panelBackgroundColor;

        // 首次打开时发放科技点
        if (!_techPointsAwarded)
        {
            AwardTechPoints();
            _techPointsAwarded = true;
        }

        StartCoroutine(DisplayPanelResultsCoroutine());
    }

    /// <summary>根据结算分数发放科技点（分数 / _techPointDivisor）</summary>
    private void AwardTechPoints()
    {
        var stats = GameStatistics.Instance;
        if (stats == null || _scoreCalculator == null) return;

        int score = _scoreCalculator.CalculateScore(stats);
        _lastEarnedTechPoints = _techPointDivisor > 0 ? score / _techPointDivisor : 0;

        if (_lastEarnedTechPoints > 0 && TechTreeManager.Instance != null)
        {
            TechTreeManager.Instance.AddTechPoints(_lastEarnedTechPoints);
        }
    }

    private System.Collections.IEnumerator DisplayPanelResultsCoroutine()
    {
        WritePanelText();
        yield return null;
        RebuildContentLayout();
        yield return null;
        Canvas.ForceUpdateCanvases();
    }

    /// <summary>写入弹窗内的结算文本（不含布局重建）</summary>
    private void WritePanelText()
    {
        var stats = GameStatistics.Instance;
        if (stats == null || _scoreCalculator == null) return;

        int score = _scoreCalculator.CalculateScore(stats);

        if (_panelTitleText != null)
            _panelTitleText.text = "结算明细";
        if (_panelScoreText != null)
            _panelScoreText.text = $"总分: {score}";
        if (_panelDetailText != null)
            _panelDetailText.text = BuildDetailText(stats, score);
    }

    /// <summary>强制重建 ScrollView Content 的布局</summary>
    private void RebuildContentLayout()
    {
        if (_panelDetailText == null) return;

        var contentRt = _panelDetailText.rectTransform.parent as RectTransform;
        if (contentRt == null) return;

        Canvas.ForceUpdateCanvases();
        UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(contentRt);
        Canvas.ForceUpdateCanvases();
        UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(contentRt);
    }

    private void OnCloseSettlement()
    {
        if (_settlementPanel != null)
            _settlementPanel.SetActive(false);
        if (_settlementOverlay != null)
            _settlementOverlay.SetActive(false);
    }

    // ==================== 主屏幕 (仅标题) ====================

    private void DisplayTitle()
    {
        if (_titleText != null)
        {
            var stats = GameStatistics.Instance;
            if (stats == null)
            {
                _titleText.text = "无统计数据";
                return;
            }
            _titleText.text = "<size=100>结算</size>\n<size=36>点击「查看结算」按钮查看本局详细数据</size>";
        }
    }

    // ==================== 详细文本构建 ====================

    private string BuildDetailText(GameStatistics stats, int score)
    {
        var sb = new System.Text.StringBuilder();
        var bd = _scoreCalculator != null
            ? _scoreCalculator.GetScoreBreakdown(stats)
            : default;

        // ── 道具 ──
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 获得的道具 ━━━━</color></size>");
        if (stats.AcquiredItems.Count == 0)
        {
            sb.AppendLine("  <color=#888888>· 无</color>");
        }
        else
        {
            foreach (var kvp in stats.AcquiredItems)
            {
                var item = kvp.Value.data;
                int count = kvp.Value.count;
                string qualityColor = item.quality switch
                {
                    ItemQuality.Legendary => "#FF8C00",
                    ItemQuality.Rare => "#4169E1",
                    ItemQuality.Uncommon => "#32CD32",
                    _ => "#CCCCCC"
                };
                string countStr = count > 1 ? $"  ×<color=#FFD700>{count}</color>" : "";
                int totalPrice = item.price * count;
                string priceStr = count > 1
                    ? $"<color=#FFD700>{totalPrice} ATP</color> <color=#888888>({item.price}×{count})</color>"
                    : $"<color=#FFD700>{item.price} ATP</color>";
                sb.AppendLine($"  <color={qualityColor}>{item.itemName}</color>  {priceStr}{countStr}");
            }
        }

        // ── 金钱 ──
        sb.AppendLine();
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 金 钱 ━━━━</color></size>");
        sb.AppendLine($"  总收入:  <color=#7FFF00>+{stats.TotalCurrencyEarned} ATP</color>");
        sb.AppendLine($"  总支出:  <color=#FF6347>-{stats.TotalCurrencySpent} ATP</color>");

        int net = stats.TotalCurrencyEarned - stats.TotalCurrencySpent;
        string netColor = net >= 0 ? "#7FFF00" : "#FF6347";
        string netSign = net >= 0 ? "+" : "";
        sb.AppendLine($"  净收入:  <color={netColor}>{netSign}{net} ATP</color>");

        // ── 探索 ──
        sb.AppendLine();
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 探 索 ━━━━</color></size>");
        AppendRoomTypeStats(sb, stats);
        sb.AppendLine($"  ── 合计 ──");
        sb.AppendLine($"  进入  <color=#87CEEB>{stats.RoomsVisited}</color> 间  |  清空  <color=#FFD700>{stats.RoomsCleared}</color> 间");

        // ── 击杀 ──
        sb.AppendLine();
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 击 杀 ━━━━</color></size>");
        if (stats.EnemiesKilled.Count == 0)
        {
            sb.AppendLine("  <color=#888888>· 无</color>");
        }
        else
        {
            foreach (var kvp in stats.EnemiesKilled)
            {
                bool isBoss = kvp.Key.Contains("Boss") || kvp.Key.Contains("boss");
                string enemyLabel = isBoss
                    ? $"  <color=#FF4500>[Boss] {kvp.Key}</color>"
                    : $"  <color=#AAA>·</color> {kvp.Key}";
                sb.AppendLine($"{enemyLabel}  ×<color=#FFD700>{kvp.Value}</color>");
            }
        }

        // ── 评分明细 ──
        sb.AppendLine();
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 评分明细 ━━━━</color></size>");

        if (_scoreCalculator != null)
        {
            sb.AppendLine($"  道具分:  <color=#32CD32>+{bd.itemScore:F0}</color>  ({bd.itemCount} 件 × {bd.itemPriceMultiplier})");
            sb.AppendLine($"  击杀分:  <color=#FF8C00>+{bd.killScore:F0}</color>  ({bd.totalKills} 个敌人)");
            sb.AppendLine($"  金钱分:  <color=#FFD700>+{bd.currencyScore:F0}</color>  (收入 {bd.currencyEarned} × {bd.currencyEarnedMultiplier})");
            if (bd.roomScore > 0)
                sb.AppendLine($"  探索分:  <color=#87CEEB>+{bd.roomScore:F0}</color>  (进入 {bd.roomsVisited}×{bd.roomVisitedScore} + 清空 {bd.roomsCleared}×{bd.roomClearedBonus})");
            if (bd.currencyPenalty > 0)
                sb.AppendLine($"  消费罚分:  <color=#FF6347>-{bd.currencyPenalty:F0}</color>  (支出 {bd.currencySpent} × {bd.currencySpentPenalty})");
        }

        // ── 科技点 ──
        sb.AppendLine();
        sb.AppendLine("<size=30><color=#FFD700>━━━━ 科技点 ━━━━</color></size>");
        if (_lastEarnedTechPoints > 0)
        {
            sb.AppendLine($"  本局获得:  <color=#7FFF00>+{_lastEarnedTechPoints}</color>  (总分 {score} ÷ {_techPointDivisor})");
            int total = TechTreeManager.Instance != null ? TechTreeManager.Instance.TechPoints : 0;
            sb.AppendLine($"  当前总计:  <color=#FFD700>{total}</color>");
        }
        else
        {
            sb.AppendLine($"  <color=#888888>本局分数不足，未获得科技点 (需 {_techPointDivisor} 分)</color>");
        }

        // ── 总分 ──
        sb.AppendLine();
        sb.AppendLine($"<size=36><color=#FFD700>══════ 总 分: {score} ══════</color></size>");

        return sb.ToString();
    }

    /// <summary>追加各房间类型的进入/清空明细</summary>
    private void AppendRoomTypeStats(System.Text.StringBuilder sb, GameStatistics stats)
    {
        // 合并 visited 和 cleared 的房间类型
        var allTypes = new HashSet<RoomType>();
        foreach (var t in stats.RoomsVisitedByType.Keys) allTypes.Add(t);
        foreach (var t in stats.RoomsClearedByType.Keys) allTypes.Add(t);

        foreach (var roomType in allTypes)
        {
            stats.RoomsVisitedByType.TryGetValue(roomType, out int visited);
            stats.RoomsClearedByType.TryGetValue(roomType, out int cleared);
            string typeName = RoomTypeToString(roomType);
            sb.AppendLine($"  {typeName}  进入 <color=#87CEEB>{visited}</color>  清空 <color=#FFD700>{cleared}</color>");
        }
    }

    /// <summary>RoomType 转中文名</summary>
    private static string RoomTypeToString(RoomType type)
    {
        return type switch
        {
            RoomType.Start => "出生点",
            RoomType.Normal => "普通房",
            RoomType.Treasure => "宝箱房",
            RoomType.Boss => "Boss房",
            RoomType.Shop => "商店",
            RoomType.Exit => "出口",
            RoomType.Hidden => "隐藏房",
            _ => type.ToString()
        };
    }
}

using UnityEngine;

/// <summary>
/// 评分明细结构体 — 各分项的分数及计算参数描述
/// </summary>
public struct ScoreBreakdown
{
    public float itemScore;
    public int itemCount;
    public float itemPriceMultiplier;

    public float killScore;
    public int totalKills;
    public float killBaseScore;
    public float bossKillBonus;

    public float currencyScore;
    public int currencyEarned;
    public float currencyEarnedMultiplier;

    public float currencyPenalty;
    public int currencySpent;
    public float currencySpentPenalty;

    public float roomScore;
    public int roomsVisited;
    public int roomsCleared;
    public float roomVisitedScore;
    public float roomClearedBonus;

    public float baseScore;
    public int totalScore;
}

/// <summary>
/// 分数计算器 (ScriptableObject) — Inspector 可配置各项权重。
/// 右键 -> Create -> Game -> Score Calculator 创建。
/// </summary>
[CreateAssetMenu(menuName = "Game/Score Calculator", fileName = "ScoreCalculator")]
public class ScoreCalculator : ScriptableObject
{
    [Header("道具分数")]
    [Tooltip("每 1 ATP 道具价格 = 多少分")]
    public float itemPriceMultiplier = 2f;

    [Header("击杀分数")]
    [Tooltip("每个普通敌人击杀基础分")]
    public float killBaseScore = 100f;
    [Tooltip("Boss 击杀额外加分（名字包含 'Boss' 时触发）")]
    public float bossKillBonus = 500f;

    [Header("金钱分数")]
    [Tooltip("每获得 1 ATP = 多少分")]
    public float currencyEarnedMultiplier = 0.5f;
    [Tooltip("每消费 1 ATP 的惩罚分")]
    public float currencySpentPenalty = 0.3f;

    [Header("房间分数")]
    [Tooltip("每进入一个房间")]
    public float roomVisitedScore = 50f;
    [Tooltip("每清空一个房间 (额外)")]
    public float roomClearedBonus = 100f;

    [Header("基础分")]
    [Tooltip("保底基础分")]
    public float baseScore = 0f;

    // ==================== 计算 ====================

    /// <summary>根据统计数据计算总分</summary>
    public int CalculateScore(GameStatistics stats)
    {
        if (stats == null) return 0;
        return GetScoreBreakdown(stats).totalScore;
    }

    /// <summary>获取评分明细（含各分项分数及计算参数）</summary>
    public ScoreBreakdown GetScoreBreakdown(GameStatistics stats)
    {
        var bd = new ScoreBreakdown
        {
            baseScore = baseScore,
            itemPriceMultiplier = itemPriceMultiplier,
            killBaseScore = killBaseScore,
            bossKillBonus = bossKillBonus,
            currencyEarnedMultiplier = currencyEarnedMultiplier,
            currencySpentPenalty = currencySpentPenalty,
            roomVisitedScore = roomVisitedScore,
            roomClearedBonus = roomClearedBonus
        };

        if (stats == null)
        {
            bd.totalScore = 0;
            return bd;
        }

        float total = baseScore;

        // 道具分: Σ(item.price × count × itemPriceMultiplier)
        bd.itemScore = 0f;
        bd.itemCount = 0;
        foreach (var kvp in stats.AcquiredItems)
        {
            bd.itemScore += kvp.Value.data.price * kvp.Value.count * itemPriceMultiplier;
            bd.itemCount += kvp.Value.count;
        }
        total += bd.itemScore;

        // 击杀分: Σ(killCount × baseScore) + Boss击杀 × bossBonus
        bd.killScore = 0f;
        bd.totalKills = 0;
        foreach (var kvp in stats.EnemiesKilled)
        {
            float perKill = kvp.Key.Contains("Boss") || kvp.Key.Contains("boss")
                ? killBaseScore + bossKillBonus
                : killBaseScore;
            bd.killScore += kvp.Value * perKill;
            bd.totalKills += kvp.Value;
        }
        total += bd.killScore;

        // 金钱分
        bd.currencyEarned = stats.TotalCurrencyEarned;
        bd.currencyScore = stats.TotalCurrencyEarned * currencyEarnedMultiplier;
        total += bd.currencyScore;

        bd.currencySpent = stats.TotalCurrencySpent;
        bd.currencyPenalty = stats.TotalCurrencySpent * currencySpentPenalty;
        total -= bd.currencyPenalty;

        // 房间分
        bd.roomsVisited = stats.RoomsVisited;
        bd.roomsCleared = stats.RoomsCleared;
        bd.roomScore = stats.RoomsVisited * roomVisitedScore + stats.RoomsCleared * roomClearedBonus;
        total += bd.roomScore;

        bd.totalScore = Mathf.Max(0, Mathf.RoundToInt(total));
        return bd;
    }
}

